SET
  @Name_98497d97 = N'Forms Automation Runner'
SET
  @Description_98497d97 = N'The role on-submit automations and entity bindings execute under. Deliberately separate from the anonymous ''Form Respondent'' role: a respondent may only create a response, while an automation must read that response back and write business records downstream. Grants read on the response entities, update on Form Responses only (so ''Forms: Upsert Respondent Person'' can stamp RespondentPersonID back onto the response), plus write on the Forms-owned automation/binding bookkeeping tables. Grants NOTHING on any binding target entity — those are added per deployment, and the set of them is the hard ceiling on what a form author can reach through a binding. Assign only to the seeded automation service user; never to a person.' EXEC [${mjSchema}].spCreateRole @ID = @ID_98497d97,
  @Name = @Name_98497d97,
  @Description = @Description_98497d97,
  @DirectoryID = @DirectoryID_98497d97,
  @DirectoryID_Clear = 1,
  @SQLName = @SQLName_98497d97,
  @SQLName_Clear = 1;

GO

